7	// Nasdaq TotalView-ITCH 5.0 message subset needed for limit-order-book
8	// reconstruction.  Only Add / Delete / Replace / Execute are parsed;
9	// all other message types are skipped without reading past the buffer.
10	//
11	// All multi-byte fields in ITCH are big-endian.
12	
13	namespace itch {
14	
15	// ─── Message types (ITCH 5.0 §4) ────────────────────────────────────────────
16	
17	enum class MsgType : char {
18	    AddOrder           = 'A',
19	    AddOrderMPID       = 'F',
20	    ExecuteOrder       = 'E',
21	    ExecuteOrderPrice  = 'C',
22	    CancelOrder        = 'X',
23	    DeleteOrder        = 'D',
24	    ReplaceOrder       = 'U',
25	    // All other types are skipped.
26	    Unknown            = '\0',
27	};
28	
29	// ─── Parsed message structs ──────────────────────────────────────────────────
30	
31	struct AddOrder {
32	    uint64_t order_ref;
33	    char     side;          // 'B' or 'S'
34	    uint32_t shares;
35	    uint32_t price;         // price * 10000 (ITCH fixed-point 4 decimals)
36	};
37	
38	struct ExecuteOrder {
39	    uint64_t order_ref;
40	    uint32_t executed_shares;
41	};
42	
43	struct DeleteOrder {
44	    uint64_t order_ref;
45	};
46	
47	struct ReplaceOrder {
48	    uint64_t old_order_ref;
49	    uint64_t new_order_ref;
50	    uint32_t shares;
51	    uint32_t price;
52	};
53	
54	// ─── Visitor callbacks ───────────────────────────────────────────────────────
55	
56	struct MessageVisitor {
57	    std::function<void(const AddOrder&)>     on_add;
58	    std::function<void(const ExecuteOrder&)> on_execute;
59	    std::function<void(const DeleteOrder&)>  on_delete;
60	    std::function<void(const ReplaceOrder&)> on_replace;
61	};
62	
63	// ─── Parser ─────────────────────────────────────────────────────────────────
64	
65	struct ParseStats {
66	    uint64_t add_count     = 0;
67	    uint64_t execute_count = 0;
68	    uint64_t delete_count  = 0;
69	    uint64_t replace_count = 0;
70	    uint64_t skipped_count = 0;
71	    uint64_t error_count   = 0;
72	};
73	
74	// Parse a buffer containing concatenated ITCH 5.0 messages.
75	// Each message is preceded by a 2-byte big-endian *length* field
76	// (the "Moldupd64" framing used by Nasdaq's sample files).
77	//
78	// Calls the appropriate visitor callback for each recognised message type.
79	// Never reads past the end of the buffer.  Unknown message types increment
80	// skipped_count and advance past them using their declared length.
81	ParseStats parse_buffer(
82	    const uint8_t* buf,
83	    std::size_t    len,
84	    MessageVisitor visitor);
85	
86	}  // namespace itch
