7	// Baseline limit-order-book engine keyed by price level using std::map
8	// (ordered, O(log n) per op).  This is the intentional 'before' baseline —
9	// the cache-unfriendly reference we will compare against a flat-array variant.
10	//
11	// Price levels are stored in fixed-point units (ITCH price * 10000, i.e. the
12	// raw uint32_t from the wire).  The public interface uses those raw units; the
13	// caller divides by 10000.0 for display.
14	
15	namespace itch {
16	
17	struct PriceLevel {
18	    uint32_t price_raw;   // fixed-point (divide by 10000 for real price)
19	    uint32_t shares;
20	};
21	
22	struct TopOfBook {
23	    std::optional<PriceLevel> best_bid;
24	    std::optional<PriceLevel> best_ask;
25	};
26	
27	// Per-order record: maps order_ref → (side, price, shares).
28	struct OrderRecord {
29	    char     side;
30	    uint32_t price_raw;
31	    uint32_t shares;
32	};
33	
34	class OrderBook {
35	public:
36	    // Apply an Add-Order message.
37	    void add(uint64_t order_ref, char side, uint32_t price_raw, uint32_t shares);
38	
39	    // Apply an Execute-Order message (partial or full fill).
40	    // Returns the executed shares actually removed (0 if order_ref unknown).
41	    uint32_t execute(uint64_t order_ref, uint32_t executed_shares);
42	
43	    // Apply a Delete-Order message.
44	    // Returns true if the order was found and removed.
45	    bool del(uint64_t order_ref);
46	
47	    // Apply a Replace-Order message.
48	    void replace(uint64_t old_ref, uint64_t new_ref, uint32_t shares, uint32_t price_raw);
49	
50	    // Best bid (highest price) and best ask (lowest price).
51	    TopOfBook top_of_book() const;
52	
53	    // Diagnostics.
54	    uint64_t error_count() const { return error_count_; }
55	    std::size_t order_count() const { return orders_.size(); }
56	
57	private:
58	    // orders_[ref] → OrderRecord (side, price, shares)
59	    std::unordered_map<uint64_t, OrderRecord> orders_;
60	
61	    // bids_[price] = total shares at that price level (highest = best bid)
62	    std::map<uint32_t, uint32_t, std::greater<uint32_t>> bids_;
63	    // asks_[price] = total shares at that price level (lowest = best ask)
64	    std::map<uint32_t, uint32_t> asks_;
65	
66	    uint64_t error_count_ = 0;
67	
68	    void _remove_shares(char side, uint32_t price_raw, uint32_t shares);
69	};
70	
71	}  // namespace itch
