6	// Trivial top-of-book signal emitted each time the book changes.
7	// Downstream consumers register a callback; the engine calls it after every update.
8	
9	namespace itch {
10	
11	struct TopOfBookSignal {
12	    double bid_price;   // best bid in real price units (raw / 10000.0)
13	    double ask_price;   // best ask in real price units
14	    double mid;         // (bid + ask) / 2.0; NaN if one side is empty
15	    uint32_t bid_shares;
16	    uint32_t ask_shares;
17	    bool valid;         // false if either side is empty
18	};
19	
20	using SignalCallback = std::function<void(const TopOfBookSignal&)>;
21	
22	// Compute a TopOfBookSignal from any type that exposes top_of_book().
23	// Works with both OrderBook and OrderBookFlat.
24	template<typename Book>
25	inline TopOfBookSignal make_signal(const Book& book) {
26	    TopOfBookSignal sig{};
27	    const TopOfBook tob = book.top_of_book();
28	    if (tob.best_bid && tob.best_ask) {
29	        sig.bid_price  = tob.best_bid->price_raw / 10000.0;
30	        sig.ask_price  = tob.best_ask->price_raw / 10000.0;
31	        sig.bid_shares = tob.best_bid->shares;
32	        sig.ask_shares = tob.best_ask->shares;
33	        sig.mid        = (sig.bid_price + sig.ask_price) / 2.0;
34	        sig.valid      = true;
35	    } else if (tob.best_bid) {
36	        sig.bid_price  = tob.best_bid->price_raw / 10000.0;
37	        sig.bid_shares = tob.best_bid->shares;
38	        sig.valid      = false;
39	    } else if (tob.best_ask) {
40	        sig.ask_price  = tob.best_ask->price_raw / 10000.0;
41	        sig.ask_shares = tob.best_ask->shares;
42	        sig.valid      = false;
43	    }
44	    return sig;
45	}
46	
47	}  // namespace itch
