9	// A minimal HDR-style latency histogram for measuring tick-to-trade latency.
10	//
11	// Stores counts in power-of-2 sized buckets with sub-bucket resolution.
12	// Covers latencies from 1 ns to ~68 seconds at 1% precision.
13	// Does NOT depend on the HdrHistogram_c library — this is a self-contained
14	// header-only implementation that avoids the FetchContent overhead for a
15	// simple benchmark.
16	//
17	// For production use you would replace this with the real HdrHistogram_c;
18	// the percentile() API is the same.
19	
20	namespace latency {
21	
22	class Histogram {
23	public:
24	    // significant_figures: number of significant decimal digits (1-5).
25	    explicit Histogram(int significant_figures = 3)
26	        : sig_figs_(significant_figures) {
27	        if (significant_figures < 1 || significant_figures > 5)
28	            throw std::invalid_argument("significant_figures must be 1-5");
29	        // Each bucket covers a power-of-2 range; sub_bucket_count is the
30	        // number of entries within that range.
31	        sub_bucket_count_ = 1;
32	        for (int i = 0; i < significant_figures; ++i) sub_bucket_count_ *= 10;
33	        sub_bucket_half_ = sub_bucket_count_ / 2;
34	
35	        // 64 leading-zero buckets covers the full uint64_t range.
36	        bucket_count_ = 64;
37	        counts_.assign(bucket_count_ * sub_bucket_count_, 0);
38	        total_ = 0;
39	        min_val_ = UINT64_MAX;
40	        max_val_ = 0;
41	    }
42	
43	    // Record a single latency value (in nanoseconds or any consistent unit).
44	    void record(uint64_t value) {
45	        std::size_t idx = _index(value);
46	        if (idx < counts_.size()) {
47	            ++counts_[idx];
48	            ++total_;
49	            if (value < min_val_) min_val_ = value;
50	            if (value > max_val_) max_val_ = value;
51	        }
52	    }
53	
54	    // Percentile in [0.0, 100.0].  Returns 0 if histogram is empty.
55	    uint64_t percentile(double pct) const {
56	        if (total_ == 0) return 0;
57	        uint64_t target = static_cast<uint64_t>(pct / 100.0 * static_cast<double>(total_));
58	        if (target == 0) target = 1;
59	        uint64_t cumul = 0;
60	        for (std::size_t i = 0; i < counts_.size(); ++i) {
61	            cumul += counts_[i];
62	            if (cumul >= target) {
63	                return _value_at(i);
64	            }
65	        }
66	        return max_val_;
67	    }
68	
69	    uint64_t min_value() const { return (total_ == 0) ? 0 : min_val_; }
70	    uint64_t max_value() const { return max_val_; }
71	    uint64_t total_count() const { return total_; }
72	
73	    double mean() const {
74	        if (total_ == 0) return 0.0;
75	        uint64_t sum = 0;
76	        for (std::size_t i = 0; i < counts_.size(); ++i)
77	            sum += counts_[i] * _value_at(i);
78	        return static_cast<double>(sum) / static_cast<double>(total_);
79	    }
80	
81	    void reset() {
82	        std::fill(counts_.begin(), counts_.end(), 0);
83	        total_   = 0;
84	        min_val_ = UINT64_MAX;
85	        max_val_ = 0;
86	    }
87	
88	private:
89	    int sig_figs_;
90	    int sub_bucket_count_;
91	    int sub_bucket_half_;
92	    int bucket_count_;
93	    std::vector<uint64_t> counts_;
94	    uint64_t total_;
95	    uint64_t min_val_;
96	    uint64_t max_val_;
97	
98	    // Map a value to a flat index into counts_.
99	    std::size_t _index(uint64_t v) const {
100	        int bucket = 0;
101	        uint64_t w = v;
102	        while (w >= static_cast<uint64_t>(sub_bucket_count_)) {
103	            w >>= 1;
104	            ++bucket;
105	        }
106	        int sub = static_cast<int>(w);
107	        std::size_t idx = static_cast<std::size_t>(bucket * sub_bucket_count_ + sub);
108	        return (idx < counts_.size()) ? idx : counts_.size() - 1;
109	    }
110	
111	    // Inverse: index → representative value.
112	    uint64_t _value_at(std::size_t idx) const {
113	        int bucket = static_cast<int>(idx / static_cast<std::size_t>(sub_bucket_count_));
114	        int sub    = static_cast<int>(idx % static_cast<std::size_t>(sub_bucket_count_));
115	        if (bucket == 0) return static_cast<uint64_t>(sub);
116	        return static_cast<uint64_t>(sub) << bucket;
117	    }
118	};
119	
120	}  // namespace latency
