1	// Tick-to-trade latency benchmark.
2	// Usage:  bench_main <itch_sample.bin>
3	//
4	// Reads a Nasdaq TotalView-ITCH 5.0 sample file (MoldUDP64-framed), rebuilds
5	// the L2 order book message-by-message, and records the wall-clock latency
6	// (CLOCK_MONOTONIC) from the start of each message parse to the signal emit.
7	// Prints p50 / p99 / p99.9 latencies in nanoseconds, and a simple stats line.
8	//
9	// When the file path argument is omitted (or the file cannot be opened), the
10	// binary falls back to a synthetic in-memory message stream so the harness can
11	// be tested without a real sample file.
12	
13	#include "itch_parser.hpp"
14	#include "order_book.hpp"
15	#include "signal.hpp"
16	#include "../common/latency_histogram.hpp"
17	
18	#include <chrono>
19	#include <cstdint>
20	#include <cstdio>
21	#include <cstring>
22	#include <fstream>
23	#include <vector>
24	
25	// ─── Monotonic clock helper ──────────────────────────────────────────────────
26	
27	static inline uint64_t now_ns() {
28	    struct timespec ts;
29	    clock_gettime(CLOCK_MONOTONIC, &ts);
30	    return static_cast<uint64_t>(ts.tv_sec) * 1'000'000'000ULL
31	         + static_cast<uint64_t>(ts.tv_nsec);
32	}
33	
34	// ─── Synthetic message generator ─────────────────────────────────────────────
35	
36	static void put_be16(uint8_t* p, uint16_t v) {
37	    p[0] = (v >> 8) & 0xff; p[1] = v & 0xff;
38	}
39	static void put_be32(uint8_t* p, uint32_t v) {
40	    p[0] = (v >> 24) & 0xff; p[1] = (v >> 16) & 0xff;
41	    p[2] = (v >>  8) & 0xff; p[3] =  v        & 0xff;
42	}
43	static void put_be64(uint8_t* p, uint64_t v) {
44	    put_be32(p,     static_cast<uint32_t>(v >> 32));
45	    put_be32(p + 4, static_cast<uint32_t>(v));
46	}
47	
48	static std::vector<uint8_t> build_synthetic_stream(int n_orders) {
49	    std::vector<uint8_t> buf;
50	    buf.reserve(static_cast<std::size_t>(n_orders) * (2 + 36));
51	
52	    for (int i = 0; i < n_orders; ++i) {
53	        const uint16_t msg_len = 36;
54	        buf.resize(buf.size() + 2 + msg_len, 0);
55	        uint8_t* p = buf.data() + buf.size() - 2 - msg_len;
56	        put_be16(p, msg_len);
57	        p[2] = 'A';
58	        const uint64_t ref   = static_cast<uint64_t>(i + 1);
59	        const char     side  = (i % 2 == 0) ? 'B' : 'S';
60	        const uint32_t price = (side == 'B') ? 1000000u + static_cast<uint32_t>(i % 10) * 100u
61	                                             : 1010000u + static_cast<uint32_t>(i % 10) * 100u;
62	        const uint32_t shares = 100u;
63	        put_be64(p + 2 + 11, ref);
64	        p[2 + 19] = static_cast<uint8_t>(side);
65	        put_be32(p + 2 + 20, shares);
66	        put_be32(p + 2 + 32, price);
67	    }
68	    return buf;
69	}
70	
71	// ─── Benchmark loop ──────────────────────────────────────────────────────────
72	
73	static void run_benchmark(const uint8_t* data, std::size_t len) {
74	    itch::OrderBook book;
75	    latency::Histogram hist(3);
76	
77	    itch::MessageVisitor visitor;
78	    visitor.on_add = [&](const itch::AddOrder& m) {
79	        const uint64_t t0 = now_ns();
80	        book.add(m.order_ref, m.side, m.price, m.shares);
81	        itch::make_signal(book);
82	        const uint64_t t1 = now_ns();
83	        hist.record(t1 - t0);
84	    };
85	    visitor.on_execute = [&](const itch::ExecuteOrder& m) {
86	        const uint64_t t0 = now_ns();
87	        book.execute(m.order_ref, m.executed_shares);
88	        itch::make_signal(book);
89	        const uint64_t t1 = now_ns();
90	        hist.record(t1 - t0);
91	    };
92	    visitor.on_delete = [&](const itch::DeleteOrder& m) {
93	        const uint64_t t0 = now_ns();
94	        book.del(m.order_ref);
95	        itch::make_signal(book);
96	        const uint64_t t1 = now_ns();
97	        hist.record(t1 - t0);
98	    };
99	    visitor.on_replace = [&](const itch::ReplaceOrder& m) {
100	        const uint64_t t0 = now_ns();
101	        book.replace(m.old_order_ref, m.new_order_ref, m.shares, m.price);
102	        itch::make_signal(book);
103	        const uint64_t t1 = now_ns();
104	        hist.record(t1 - t0);
105	    };
106	
107	    const itch::ParseStats stats = itch::parse_buffer(data, len, visitor);
108	
109	    printf("=== ITCH Bench: tick-to-trade latency ===\n");
110	    printf("Messages parsed:  add=%llu  execute=%llu  delete=%llu  replace=%llu\n",
111	           (unsigned long long)stats.add_count,
112	           (unsigned long long)stats.execute_count,
113	           (unsigned long long)stats.delete_count,
114	           (unsigned long long)stats.replace_count);
115	    printf("Skipped: %llu  Errors: %llu\n",
116	           (unsigned long long)stats.skipped_count,
117	           (unsigned long long)stats.error_count);
118	    printf("Latency (ns):  p50=%llu  p99=%llu  p99.9=%llu  mean=%.1f  max=%llu\n",
119	           (unsigned long long)hist.percentile(50.0),
120	           (unsigned long long)hist.percentile(99.0),
121	           (unsigned long long)hist.percentile(99.9),
122	           hist.mean(),
123	           (unsigned long long)hist.max_value());
124	    printf("Total timed events: %llu\n", (unsigned long long)hist.total_count());
125	}
126	
127	// ─── main ────────────────────────────────────────────────────────────────────
128	
129	int main(int argc, char** argv) {
130	    std::vector<uint8_t> data;
131	
132	    if (argc >= 2) {
133	        std::ifstream f(argv[1], std::ios::binary | std::ios::ate);
134	        if (!f) {
135	            fprintf(stderr, "Cannot open '%s' — falling back to synthetic stream.\n", argv[1]);
136	        } else {
137	            const std::streamsize sz = f.tellg();
138	            f.seekg(0);
139	            data.resize(static_cast<std::size_t>(sz));
140	            f.read(reinterpret_cast<char*>(data.data()), sz);
141	            fprintf(stderr, "Loaded %lld bytes from '%s'.\n", (long long)sz, argv[1]);
142	        }
143	    }
144	
145	    if (data.empty()) {
146	        fprintf(stderr, "Using synthetic stream (100,000 Add Order messages).\n");
147	        data = build_synthetic_stream(100'000);
148	    }
149	
150	    run_benchmark(data.data(), data.size());
151	    return 0;
152	}
